// --- BUILDER ------------------------------------------------------------------

const DM_OPTION_KEYS = ["A", "B", "C", "D"] as const;

function buildDmOptions(
  correctText: string,
  distractors: string[],
  seed: number
) {
  const answerIndex = seed % DM_OPTION_KEYS.length;
  const wrongs = distractors.slice(0, 3);
  const texts = [...wrongs];
  texts.splice(answerIndex, 0, correctText);
  return {
    options: texts.map((text, i) => ({
      key: DM_OPTION_KEYS[i],
      text,
    })),
    answer: DM_OPTION_KEYS[answerIndex],
  };
}

function buildDmQuestion(
  input: DmCuratedInput,
  inputIndex: number
): UCATQuestion {
  const base = {
    id: `user-curated-dm-${String(inputIndex + 1).padStart(4, "0")}`,
    section: "dm" as const,
    subtype: input.subtype,
    title: "Decision Making Practice",
    leftTitle: input.leftTitle ?? "Information",
    tags: input.tags ?? ["text-stem", "medium"],
    stimulus: input.stimulus,
    visual: (input as { visual?: UCATChartVisual }).visual,
    question: input.question,
    explanation: input.explanation,
  };

  if (input.kind === "single") {
    return {
      ...base,
      ...buildDmOptions(input.correct, input.distractors, inputIndex),
    };
  }

  if (input.kind === "yes-no") {
    return {
      ...base,
      questionType: "yes-no" as const,
      instruction: input.instruction,
      yesNoStatements: input.yesNoStatements as Array<{
        id: string;
        text: string;
        answer: UCATYesNoValue;
      }>,
    };
  }

  return {
    ...base,
    questionType: "drag-category" as const,
    instruction: input.instruction,
    categories: input.categories,
    categoryItems: input.categoryItems,
  };
}

export const CURATED_DM_QUESTIONS_FROM_CURATED: UCATQuestion[] =
  USER_CURATED_DM_INPUTS.map(buildDmQuestion);

// --- RAW VENN INPUTS ----------------------------------------------------------
// Gemini provides: set labels + number per region + questions.
// Builder supplies all coordinates automatically from fixed templates.

export type DmVenn2RawInput = {
  kind: "venn-2";
  title: string;
  context: string;
  setA: string;
  setB: string;
  aOnly: number;
  bOnly: number;
  both: number;
  questions: Array<{
    question: string;
    correct: string;
    distractors: [string, string, string];
    explanation: string;
  }>;
};

export type DmVenn3RawInput = {
  kind: "venn-3";
  title: string;
  context: string;
  setA: string;
  setB: string;
  setC: string;
  aOnly: number;
  bOnly: number;
  cOnly: number;
  aAndBOnly: number;
  aAndCOnly: number;
  bAndCOnly: number;
  all3: number;
  questions: Array<{
    question: string;
    correct: string;
    distractors: [string, string, string];
    explanation: string;
  }>;
};

// 4-set "ring" layout: A↔B (top), A↔C (left), B↔D (right), C↔D (bottom).
// A and D do NOT overlap; B and C do NOT overlap → exactly 8 visible regions.
// setA = top-left (circle), setB = top-right (rectangle),
// setC = bottom-left (diamond), setD = bottom-right (hexagon).
export type DmVenn4RawInput = {
  kind: "venn-4";
  title: string;
  context: string;
  setA: string;
  setB: string;
  setC: string;
  setD: string;
  aOnly: number;
  bOnly: number;
  cOnly: number;
  dOnly: number;
  aAndB: number;  // A∩B only (top overlap)
  aAndC: number;  // A∩C only (left overlap)
  bAndD: number;  // B∩D only (right overlap)
  cAndD: number;  // C∩D only (bottom overlap)
  questions: Array<{
    question: string;
    correct: string;
    distractors: [string, string, string];
    explanation: string;
  }>;
};

