// --- RAW CHART YES/NO INPUTS --------------------------------------------------
// Gemini provides: chart data (numbers + labels) + yes/no statements.
// Builder calculates max, assigns IDs, and builds the correct visual type.

type DmChartYesNoStatement = {
  text: string;
  answer: "Yes" | "No";
  explanation: string;
};

export type DmBarYesNoRaw = {
  kind: "chart-yes-no";
  chartType: "bar";
  title: string;
  yLabel: string;
  context: string;
  data: Array<{ label: string; value: number }>;
  yesNoStatements: DmChartYesNoStatement[];
};

export type DmLineYesNoRaw = {
  kind: "chart-yes-no";
  chartType: "line";
  title: string;
  yLabel: string;
  context: string;
  data: Array<{ label: string; value: number }>;
  yesNoStatements: DmChartYesNoStatement[];
};

export type DmGroupedBarYesNoRaw = {
  kind: "chart-yes-no";
  chartType: "grouped-bar";
  title: string;
  yLabel: string;
  context: string;
  seriesLabels: string[];
  groups: Array<{ label: string; values: number[] }>;
  yesNoStatements: DmChartYesNoStatement[];
};

export type DmChartYesNoRawInput =
  | DmBarYesNoRaw
  | DmLineYesNoRaw
  | DmGroupedBarYesNoRaw;

